def test_spec_632_xml(run):
    """spec example 632 (raw_html) rendered as xml"""
    r = run(args=['-t', 'xml'], stdin=b'<a href="\\"">\n')
    assert r.stdout == b'<?xml version="1.0" encoding="UTF-8"?>\n<!DOCTYPE document SYSTEM "CommonMark.dtd">\n<document xmlns="http://commonmark.org/xml/1.0">\n  <paragraph>\n    <text xml:space="preserve">&lt;a href=&quot;&quot;&quot;&gt;</text>\n  </paragraph>\n</document>\n'
    assert r.stderr == b''
    assert r.returncode == 0


def test_spec_636_xml(run):
    """spec example 636 (hard_line_breaks) rendered as xml"""
    r = run(args=['-t', 'xml'], stdin=b'foo  \n     bar\n')
    assert r.stdout == b'<?xml version="1.0" encoding="UTF-8"?>\n<!DOCTYPE document SYSTEM "CommonMark.dtd">\n<document xmlns="http://commonmark.org/xml/1.0">\n  <paragraph>\n    <text xml:space="preserve">foo</text>\n    <linebreak />\n    <text xml:space="preserve">bar</text>\n  </paragraph>\n</document>\n'
    assert r.stderr == b''
    assert r.returncode == 0


